    function checkMediaQuery() {
    if (window.matchMedia("(max-width: 900px), (max-width: 1200px), (orientation: portrait) and (min-width: 500px) and (max-width: 900px)").matches) {
        $("#moreBtn").fadeIn();
        if ($('.uk-article-content').has('h1,h2,h3,h4,h5,h6').length) {
            $("#menuBtn").fadeIn();
        }
    } else {
        $("#moreBtn").fadeOut();
        $("#menuBtn").fadeOut();
    }
}

// 初始化时检查一次
checkMediaQuery();

// 监听窗口大小变化
window.addEventListener('resize', checkMediaQuery);

    
    //目录树
    const outline = new Outline({
    title :  '', 
    selector : 'h1,h2,h3,h4,h5,h6',
    position : 'sticky',
    showCode : false,
    parentElement : '.menusx',
    articleElement : '.uk-article-content',
    showNavModalFirst:false,
    reader : {
        title:document.getElementsByClassName("uk-article-title")[0],
        target:'.uk-article-content',
        allowSpeak:true
        },
    });
    //目录树
    const outline2 = new Outline({
    title :  '', 
    selector : 'h1,h2,h3,h4,h5,h6',
    position : 'sticky',
    showCode : false,
    parentElement : '.menusxx',
    articleElement : '.uk-article-content',
    showNavModalFirst:false,
    });
const handler = function(attrs) {
  this.attr()
  $('img.lazyload')
  .visibility({
    type       : 'image',
    transition : 'fade in',
    duration   : 1000,
  });
 Fancybox.bind('[data-fancybox]', {
      groupAttr:false,
      Toolbar: {
    display: {
      left: ["infobar"],
      middle: [
        "zoomIn",
        "zoomOut",
        "toggle1to1",
        "rotateCCW",
        "rotateCW",
        "flipX",
        "flipY",
      ],
      right: ["slideshow", "thumbs", "close"],
    },
  },
});
}
outline.$on("enterReading", handler)
});
